contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: takes an amount to deposit and then tries to withdraw
    function run(uint deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(address(this).balance >= deposit, "insufficient balance for deposit");
        // record before-values
        uint beforeReported = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeCbal = address(c).balance;

        // attempt to addToBalance sending `deposit` wei
        bool addReverted;
        c.addToBalance{value: deposit}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            addReverted = true;
        } else {
            addReverted = false;
        }

        // record after addToBalance
        uint midReported = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint midCbal = address(c).balance;

        // Now attempt to withdraw
        bool withdrawReverted;
        c.withdrawBalance(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        // record after withdraw
        uint afterReported = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterCbal = address(c).balance;

        // General rule:
        // 1) If withdraw succeeded then reported balance for this address is zero.
        // 2) If withdraw succeeded then contract's ETH balance decreased by at most the reported balance just before withdraw (i.e., it did not send more than it held for that user).
        // 3) If withdraw reverted then reported and contract balances remain as before the withdraw attempt.
        assert(
            (
                (!withdrawReverted) && (afterReported == 0) && (midCbal - afterCbal <= midReported)
            )
            ||
            (
                (withdrawReverted) && (afterReported == midReported) && (afterCbal == midCbal)
            )
        );
    }

    // allow receiving ETH when C sends funds back
    receive() external payable {}
}

