pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 deposit) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= deposit);
        uint256 beforeReported;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeReported = __r; } catch { return; }
        uint beforeCbal = address(c).balance;
        bool addReverted;
        try c.addToBalance{value: deposit}() {
            addReverted = false;
        } catch {
            addReverted = true;
        }
        uint256 midReported;
        try c.getBalance(address(this)) returns (uint256 __r) { midReported = __r; } catch { return; }
        uint midCbal = address(c).balance;
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint256 afterReported;
        try c.getBalance(address(this)) returns (uint256 __r) { afterReported = __r; } catch { return; }
        uint afterCbal = address(c).balance;
        assertTrue((
                (!withdrawReverted) && (afterReported == 0) && (midCbal - afterCbal <= midReported)
            )
            ||
            (
                (withdrawReverted) && (afterReported == midReported) && (afterCbal == midCbal)
            ));
    }

    function testFuzz_run(uint256 deposit) public {
        _run(deposit);
    }

    receive() external payable {}
}
